from typing import List

class Solution:
    def sumCounts(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            seen = [False] * 101  # since nums[i] <= 100
            distinct = 0
            for j in range(i, n):
                val = nums[j]
                if not seen[val]:
                    seen[val] = True
                    distinct += 1
                total += distinct * distinct
        return total

