class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        # Find the length of the longest sequential prefix starting at index 0
        L = 1
        for i in range(1, len(nums)):
            if nums[i] == nums[i-1] + 1:
                L += 1
            else:
                break
        total = sum(nums[:L])
        num_set = set(nums)
        x = total
        while x in num_set:
            x += 1
        return x

