class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        # Precompute primes up to 100 using sieve
        is_prime = [True] * 101
        is_prime[0] = is_prime[1] = False
        for i in range(2, 101):
            if is_prime[i]:
                for j in range(i*i, 101, i):
                    is_prime[j] = False
        # Find first and last prime indices
        first = None
        last = None
        for i, num in enumerate(nums):
            if is_prime[num]:
                if first is None:
                    first = i
                last = i
        # According to constraints, at least one prime exists
        return last - first

class Solution:
    def scoreOfString(self, s: str) -> int:
        total = 0
        for i in range(len(s)-1):
            total += abs(ord(s[i]) - ord(s[i+1]))
        return total

class Solution:
    def isValid(self, word: str) -> bool:
        if len(word) < 3:
            return False
        vowels = set('aeiouAEIOU')
        for ch in word:
            if not (ch.isdigit() or ch.isalpha()):
                return False
        if not any(ch in vowels for ch in word):
            return False
        if not any(ch.isalpha() and ch not in vowels for ch in word):
            return False
        return True

