class Solution:
    def validStrings(self, n: int) -> List[str]:
        result = []
        def backtrack(current: str):
            if len(current) == n:
                result.append(current)
                return
            if not current or current[-1] != '0':
                backtrack(current + '0')
            backtrack(current + '1')
        backtrack('')
        return result

class Solution:
    def getSmallestString(self, s: str) -> str:
        n = len(s)
        best = s
        for i in range(n-1):
            if (int(s[i]) % 2) == (int(s[i+1]) % 2):
                swapped = s[:i] + s[i+1] + s[i] + s[i+2:]
                if swapped < best:
                    best = swapped
        return best

